import {COMPOSITIONS} from './onboarding-e14b41d62339.mjs';
import {directionLinks,directionChoice,resolveDirectionChoice} from './direction-model-e14b41d62339.mjs';
import {orderedGroups,orderedLabels} from './catalog-order-e14b41d62339.mjs';
import * as D from './domain-e14b41d62339.mjs';
import {effectiveActivity} from './activity-policy-e14b41d62339.mjs';
import {setTaskSources} from './stage-model-e14b41d62339.mjs';
import {rememberRecordChange} from './rebuild-model-e14b41d62339.mjs';
import {e,num} from './views-e14b41d62339.mjs';
import {button} from './rebuild-views-e14b41d62339.mjs';
export function createConnectionUI({getState,getUI,navigate,tasks,save,openModal,closeModal,toast,entityReplace}){
 let activeDirection=null,directionOrigin='growth';
 function direction(name,{origin=directionOrigin}={}){directionOrigin=origin;if(!COMPOSITIONS.includes(name))throw Error('培养方向不存在');activeDirection=name;const s=getState(),links=directionLinks(s,name);openModal(name,`<div class="direction-detail"><p class="quiet-note">固定标签把真实投入带到这里。投入与能力自评各自保留。</p><div class="catalog-list">${links.map(v=>button('direction-edit-label',`<span><strong>${e(v.activity.name)}</strong><small>${e(v.activity.category)} · ${v.main?'主要培养':'少量关联'}${v.activity.archived?' · 已归档':''}</small></span><span aria-hidden="true">›</span>`,v.activity.id,'catalog-row')).join('')||'<p class="direction-empty">从一个固定标签开始关联。</p>'}</div>${button('direction-pick-label','关联固定标签','','primary')}<section class="r-section"><h3>培养明细</h3>${s.skills.filter(k=>k.composition===name&&k.status!=='archived').map(k=>button('direction-skill',`<span><strong>${e(k.name)}</strong><small>${k.kind==='investment'?'投入积累':'投入与能力自评'} · ${num(D.skillTotals(s,k.id).growthPoints)} 分</small></span><span aria-hidden="true">›</span>`,k.id,'catalog-row')).join('')||'<p class="quiet-note">关联固定标签后即可积累；具体技能也可单独建立。</p>'}</section></div>`);const dialog=document.querySelector('#dialog');dialog.classList.add('catalog-panel');const back=dialog.querySelector('.close-button');back.classList.add('catalog-back');back.textContent=directionOrigin==='settings'?'‹ 个人':'‹ 成长';back.setAttribute('aria-label',directionOrigin==='settings'?'返回个人':'返回成长');dialog.querySelector('.dialog-header').prepend(back);}
 function pickDirectionLabel(){const s=getState(),name=activeDirection;openModal('关联到'+name,`<div class="catalog-list">${orderedGroups(s).filter(g=>!g.archived).map(g=>`<section><h3>${e(g.name)}</h3>${orderedLabels(s,g.id).filter(a=>!a.archived).map(a=>{const p=effectiveActivity(s,a);return button('direction-link-label',`<span><strong>${e(a.name)}</strong><small>当前主项：${e(s.skills.find(k=>k.id===p.mainSkillId)?.name??'仅记录时间')}</small></span><span aria-hidden="true">›</span>`,a.id,'catalog-row');}).join('')}</section>`).join('')}</div>`,{context:{onClose:()=>direction(name)}});}
 function choose(){const s=getState();openModal('标签关联',`<input id="relation-search" type="search" placeholder="搜索固定标签" aria-label="搜索固定标签"><div id="relation-labels">${s.activities.map(a=>button('edit-relations',`${e(a.category)} / ${e(a.name)}`,a.id,'r-task-row',`data-search="${e(a.category+' '+a.name)}"`)).join('')}</div>`);document.querySelector('#relation-search').oninput=ev=>{const q=ev.target.value.trim().toLowerCase();document.querySelectorAll('#relation-labels button').forEach(b=>b.hidden=!b.dataset.search.toLowerCase().includes(q));};}
 async function edit(id,{onReturn=null,directionName=null}={}){
  const s=getState(),a=s.activities.find(a=>a.id===id);if(!a)throw Error('标签不存在');
  if(directionName&&!COMPOSITIONS.includes(directionName))throw Error('培养方向不存在');
  const p=effectiveActivity(s,a),linked=s.plans.filter(t=>t.activityIds.includes(id)&&!t.archived).map(t=>t.id);
  const current=s.skills.find(k=>k.id===p.mainSkillId),target=directionName?(current?.composition===directionName?current.id:s.skills.find(k=>k.composition===directionName&&k.kind==='investment'&&k.status!=='archived')?.id??directionChoice(directionName)):p.mainSkillId??'';
  const available=s.skills.filter(k=>(!directionName||k.composition===directionName)&&(k.status!=='archived'||!directionName&&k.id===p.mainSkillId));
  const virtual=COMPOSITIONS.filter(name=>(!directionName||name===directionName)&&!s.skills.some(k=>k.composition===name&&k.kind==='investment'&&k.status!=='archived'));
  await tasks.open({
   id:directionName?'relations-direction:'+COMPOSITIONS.indexOf(directionName)+':'+id:'relations:'+id,kind:'relations',onReturn,title:a.name+' · 关联',
   extra:directionName?{directionName,activityId:id}:{},submit:directionName?'确认关联到'+directionName:'保存',
   original:{activity:a,tasks:s.plans},initial:{mainSkillId:target,relatedSkillIds:p.relatedSkillIds,taskIds:linked},
   body:(values,original)=>{
    // Only a direction placeholder may follow a newly created anchor. Concrete
    // IDs and explicit nulls retain their identity, even when no longer valid.
    const anchor=directionName&&values.mainSkillId===directionChoice(directionName)?s.skills.find(k=>k.composition===directionName&&k.kind==='investment'&&k.status!=='archived'):null;
    if(anchor)values.mainSkillId=anchor.id;
    const choices=virtual,concrete=available,selected=s.skills.find(k=>k.id===values.mainSkillId);
    const invalid=directionName&&!choices.some(name=>directionChoice(name)===values.mainSkillId)&&!concrete.some(k=>k.id===values.mainSkillId);
    const invalidLabel=!values.mainSkillId?'请选择本次方向中的主要培养项':(selected?.name??'原培养项')+(selected?.status==='archived'?' · 已归档':selected?' · 已不属于本方向':' · 已不存在')+'，请重新选择';
    const originalMain=s.skills.find(k=>k.id===effectiveActivity(s,original.activity).mainSkillId);
    return `${directionName?`<section class="direction-context"><h3>关联到 ${e(directionName)}</h3><p>原主项：<strong data-original-main>${e(originalMain?.name??'仅记录时间')}</strong></p><p>本次方向：<strong>${e(directionName)}</strong>。确认后使用下方主要培养项，替换原主项；返回不改变已保存配置。</p></section>`:''}<div class="r-connections" aria-label="固定标签与培养、任务的关系图"><div class="r-connection-root">${e(a.name)}</div><div class="r-connection-branches"><div><h3>${directionName?'本次主要培养':'主要培养'}</h3><label><span class="sr-only">主要培养项</span><select name="mainSkillId">${directionName?'':'<option value="">仅记录时间</option>'}${invalid?`<option value="${e(values.mainSkillId??'')}" data-invalid-direction>${e(invalidLabel)}</option>`:''}${choices.map(name=>`<option value="${directionChoice(name)}">${e(name)}投入 · 只积累时间</option>`).join('')}${concrete.map(k=>`<option value="${e(k.id)}">${e(k.name)}${k.kind==='investment'?' · 投入':''}</option>`).join('')}</select></label></div><details ${p.relatedSkillIds.length?'open':''}><summary>少量关联培养</summary>${s.skills.filter(k=>k.kind!=='investment').map(k=>`<label class="check"><input type="checkbox" name="relatedSkillIds" value="${e(k.id)}">${e(k.name)}</label>`).join('')||'<p>尚无具体技能。</p>'}</details><div><h3>阶段任务</h3>${s.plans.filter(t=>!t.archived||linked.includes(t.id)).map(t=>`<label class="check"><input type="checkbox" name="taskIds" value="${e(t.id)}">${e(s.phases.find(p=>p.id===t.phaseId)?.title??'旧阶段')} / ${e(t.title)}</label>`).join('')||'<p>先在阶段中建立任务。</p>'}</div></div></div><p class="quiet-note">每个勾选就是一条关联。本次保存只影响之后的新记录；任务关系从保存时刻生效，已有记录与当前计时保留。</p>${directionName?'':button('recalculate-relations','调整明确的历史范围',id,'text-button')}`;
   },
   onSave:async(f,{commit,original})=>{
    const choice=f.get('mainSkillId')||null,related=[...new Set(f.getAll('relatedSkillIds'))].filter(x=>x!==choice),tasksSelected=f.getAll('taskIds');
    if(!choice&&related.length)throw Error('先选择主要培养项，或取消关联');
    await commit(s=>{
     if(JSON.stringify(s.activities.find(a=>a.id===id))!==JSON.stringify(original.activity)||JSON.stringify(s.plans)!==JSON.stringify(original.tasks))throw Error('关联已在其他页面变化，请核对后保存');
     if(directionName&&choice!==directionChoice(directionName)&&!s.skills.some(k=>k.id===choice&&k.composition===directionName&&k.status!=='archived'))throw Error('请选择本次方向中的主要培养项');
     const main=resolveDirectionChoice(s,choice);if(main&&!s.skills.some(k=>k.id===main))throw Error('培养项不存在');
     s.activities[s.activities.findIndex(a=>a.id===id)]={...original.activity,growthMode:main?'override':'none',mainSkillId:main,relatedSkillIds:related,explicitlyExcluded:!main};
     for(const task of [...s.plans]){const has=task.activityIds.includes(id),want=tasksSelected.includes(task.id);if(has!==want)s=setTaskSources(s,task.id,want?[...task.activityIds,id]:task.activityIds.filter(x=>x!==id));}return s;
    });
    toast(directionName?'已关联到'+directionName:'标签与任务关联已保存');
   }
  });
 }
 function resume(draft){const name=draft.payload?.directionName;return name?edit(draft.payload.activityId,{directionName:name,onReturn:()=>direction(name,{origin:'settings'})}):edit(draft.id.slice('relations:'.length));}
 async function recalculate(id){await tasks.leave();const s=getState(),today=D.dateKey(Date.now(),s.timeZone),a=s.activities.find(a=>a.id===id),policy=effectiveActivity(s,a);let preview=null;openModal('指定历史范围',`<p>把「${e(a.name)}」当前培养配置应用到所选历史。其他标签和运行中的记录保留。</p><div class="form-row"><label>开始<input name="start" type="date" value="${today}" required></label><label>结束<input name="end" type="date" value="${today}" required></label></div><label class="check"><input type="checkbox" name="tasks">同时把当前已关联任务纳入该历史范围</label><div class="preview-box" data-relations-preview hidden></div>`,{submit:'预览并确认',onSubmit:async f=>{const x=f.get('start'),y=f.get('end');if(!D.isDate(x)||!D.isDate(y)||x>y||D.addDays(x,365)<y)throw Error('请选择最多366天的日期');const from=D.dayStart(x,s.timeZone),to=D.dayStart(D.addDays(y,1),s.timeZone),signature=JSON.stringify([...f]);const change=state=>{const before=D.copy(state);if(JSON.stringify(effectiveActivity(state,state.activities.find(a=>a.id===id)))!==JSON.stringify(policy))throw Error('标签配置已变化，请重新预览');const rows=[];for(const row of state.sessions){if(row.activityId!==id||row.end<=from||row.start>=to){rows.push(row);continue;}const cuts=[row.start,...[from,to].filter(t=>t>row.start&&t<row.end),row.end].sort((a,b)=>a-b);for(let i=0;i<cuts.length-1;i++){const start=cuts[i],end=cuts[i+1],part={...row,id:i?row.id+':recalc:'+start:row.id,start,end,version:row.version+1};if(start>=from&&end<=to)Object.assign(part,{mainSkillId:policy.mainSkillId,relatedSkillIds:[...policy.relatedSkillIds]});rows.push(part);for(const m of state.moments)if(m.sessionId===row.id&&m.at>=start&&m.at<end)m.sessionId=part.id;}}state.sessions=rows;
    if(f.has('tasks'))for(const task of state.plans.filter(t=>t.activityIds.includes(id))){const versions=task.sourceVersions??[{at:0,activityIds:task.activityIds,skillIds:task.skillIds,groupIds:task.groupIds??[],active:!task.archived}],bounds=[...new Set([...versions.map(v=>v.at),from,to])].sort((a,b)=>a-b);task.sourceVersions=bounds.map(at=>{const prior=versions.filter(v=>v.at<=at).at(-1)??{activityIds:[],skillIds:[],groupIds:[],active:true};return {...D.copy(prior),at,...(at>=from&&at<to?{activityIds:[...new Set([...prior.activityIds,id])],active:true}:{})};});}
    return rememberRecordChange(before,state);};
   const basis=getState(),previewKey=signature+':'+basis.revision;const candidate=change(D.copy(basis));if(preview!==previewKey){preview=previewKey;const el=document.querySelector('[data-relations-preview]');el.hidden=false;el.innerHTML='<strong>培养变化</strong>'+s.skills.map(k=>({k,b:D.skillTotals(getState(),k.id).realPoints,a:D.skillTotals(candidate,k.id).realPoints})).filter(v=>v.a!==v.b).map(v=>`<p>${e(v.k.name)}：${num(v.b)} → ${num(v.a)} 分</p>`).join('')+'<p>确认后可从时间概览撤销。</p>';return;}await save(state=>{if(state.revision!==basis.revision)throw Error('记录已变化，请重新预览后确认');return change(state);});await closeModal();toast('历史范围已更新，可撤销');}});}
 return {edit,direction,resume,actions:{'growth-direction':name=>direction(name,{origin:'growth'}),'direction-skill':async id=>{const name=activeDirection;await closeModal({resume:false});getUI().directionReturn={name,skillId:id};return navigate('skillDetail',{navPage:'growth',skillId:id,detailPlanId:null,revealSources:false,sourceLimit:30});},'direction-pick-label':pickDirectionLabel,'direction-edit-label':id=>{const name=activeDirection;return edit(id,{onReturn:()=>direction(name)});},'direction-link-label':id=>{const name=activeDirection;return edit(id,{directionName:name,onReturn:()=>direction(name)});},'open-relations':choose,'edit-relations':edit,'recalculate-relations':recalculate}};
}
